{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "monthly_visitors_header_stack",
        "visitor_table",
        "analysis_h2",
        "analysis_text"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Website Visitor Trends Overview",
        "variant": "h1"
      },
      "children": []
    },
    "monthly_visitors_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "icon_graph",
        "monthly_visitors_h2"
      ]
    },
    "icon_graph": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000357_01_1_graph-up.svg"
      },
      "children": []
    },
    "monthly_visitors_h2": {
      "type": "Text",
      "props": {
        "text": "Monthly Website Visitors Data",
        "variant": "h2"
      },
      "children": []
    },
    "visitor_table": {
      "type": "Table",
      "props": {
        "title": "Website Visitors Over Time",
        "domain": "status",
        "preferredPresentation": "cards",
        "primaryColumn": "Month",
        "highlightColumns": ["Visitors"],
        "columns": [
          {
            "key": "Month",
            "label": "Month"
          },
          {
            "key": "Visitors",
            "label": "Visitors"
          }
        ],
        "rows": [
          {
            "Month": "Jan",
            "Visitors": 1000
          },
          {
            "Month": "Feb",
            "Visitors": 1200
          },
          {
            "Month": "Mar",
            "Visitors": 1100
          },
          {
            "Month": "Apr",
            "Visitors": 1350
          },
          {
            "Month": "May",
            "Visitors": 1400
          }
        ]
      },
      "children": []
    },
    "analysis_h2": {
      "type": "Text",
      "props": {
        "text": "Visitor Trend Analysis",
        "variant": "h2"
      },
      "children": []
    },
    "analysis_text": {
      "type": "Text",
      "props": {
        "text": "The website visitor numbers show an overall positive trend from January to May. After an initial increase from 1000 in January to 1200 in February, there was a slight dip to 1100 in March. However, visitors rebounded strongly in April, reaching 1350, and continued to climb to 1400 in May, indicating consistent growth with minor fluctuations.",
        "variant": "body"
      },
      "children": []
    }
  }
}
